/**
 * Storno objednavky (2026). Na rozdil od hromadneho storna v orders.php
 * jde pres novy e-shop: ten pohlida stav, uvolni rezervace ve skladu
 * a u zaplacene objednavky spocita vratku. Penize posila obchod prevodem.
 */
public function cancelAction()
{
    global $db;
    legacy_db();

    $id = post_param('id');
    if (!is_post()) {
        return $this->redirect(admin_url('order', array('id' => $id)));
    }

    $order = $db->one("SELECT * FROM orders WHERE id = " . $db->quote($id));
    if ($order === null) {
        return $this->notFound('Objednávka ' . $id . ' neexistuje');
    }
    if ($order['status'] == 'cancelled') {
        flash('Objednávka už je stornovaná', 'error');

        return $this->redirect(admin_url('order', array('id' => $id)));
    }

    $reason = trim((string) post_param('reason'));
    if ($reason == '') {
        $reason = 'Storno v administraci';
    }

    try {
        $this->commandBus->dispatch(new CancelOrder(OrderId::fromString($id), $reason));
    } catch (HandlerFailedException $e) {
        if (count($e->getWrappedExceptions(InvalidOrderStateTransitionException::class)) == 0) {
            throw $e;
        }
        flash('Objednávku ve stavu „' . order_state_label($order['status']) . '“ nejde stornovat', 'error');

        return $this->redirect(admin_url('order', array('id' => $id)));
    }

    // vratku spocital novy e-shop, tady ji jen oznamime
    $order = $db->one("SELECT * FROM orders WHERE id = " . $db->quote($id));
    $refund = (int) $order['refund_amount_in_cents'];

    audit_log('order', $id, 'storno', array('reason' => $reason, 'refund' => $refund, 'currency' => $order['refund_currency']));

    $note = 'Storno: ' . $reason;
    if ($refund > 0) {
        $note .= "\nVrátit zákazníkovi " . format_price($refund, $order['refund_currency']) . ' převodem.';
    }
    $db->exec("INSERT INTO order_notes (order_id, author, note, created_at) VALUES (" . $db->quote($id) . ", "
        . $db->quote(auth_login_name()) . ", " . $db->quote($note) . ", '" . date('Y-m-d H:i:s') . "')");

    $c = $db->one("SELECT email FROM customers WHERE id = " . $db->quote($order['customer_id']));
    if ($c) {
        $body = "Dobrý den,\n\nvaše objednávka " . $id . " byla stornována.\n";
        if ($refund > 0) {
            $body .= "Zaplacenou částku " . format_price($refund, $order['refund_currency']) . " vám vrátíme na účet.\n";
        }
        send_mail($c['email'], 'Vaše objednávka byla stornována', $body);
    }

    cache_delete('dashboard_stats');

    flash($refund > 0
        ? 'Objednávka stornována, zákazníkovi vrátit ' . format_price($refund, $order['refund_currency'])
        : 'Objednávka stornována');

    return $this->redirect(admin_url('order', array('id' => $id)));
}

