    if ($order['status'] == 'cancelled') {
        flash('Objednávka už je stornovaná', 'error');

        return $this->redirect(admin_url('order', array('id' => $id)));
    }

    $reason = trim((string) post_param('reason'));
    if ($reason == '') {
        $reason = 'Storno v administraci';
    }

    try {
        $this->commandBus->dispatch(new CancelOrder(OrderId::fromString($id), $reason));
    } catch (HandlerFailedException $e) {
        if (count($e->getWrappedExceptions(InvalidOrderStateTransitionException::class)) == 0) {
            throw $e;
        }
        flash('Objednávku ve stavu „' . order_state_label($order['status']) . '“ nejde stornovat', 'error');

        return $this->redirect(admin_url('order', array('id' => $id)));
    }

